package io.karandash.plugins.formats

import io.karandash.api.finding.ReportMetadata
import io.karandash.api.finding.SkippedRuleInfo
import io.karandash.api.finding.ValidationReport
import io.karandash.api.finding.summarize
import io.karandash.models.finding.Finding
import io.karandash.models.finding.Location
import io.karandash.models.finding.Severity
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFalse
import kotlin.test.assertTrue

/** The summary footer line, as the English summary ends. */
internal const val SUMMARY_FOOTER =
    "_Generated by [karandash](https://github.com/karandash/karandash) · React \uD83D\uDC4E on a finding to mark it as a false positive._"

/** A summary that would exceed 10 KB collapses its long sections and ends within the limit. */
class MarkdownSummarySizeLimitTest {
    private fun finding(i: Int) =
        Finding(
            severity = if (i % 3 == 0) Severity.ERROR else Severity.WARNING,
            message = "Finding $i in a large MR: the handler swallows the error and the retry loop never backs off, so the " +
                "service hammers the upstream when it is down",
            rule = "rule-${i % 7}",
            location = Location.FileRef(path = "src/main/kotlin/module$i/File$i.kt", line = i + 1),
            suggestion = "Log the error and add exponential backoff to the retry loop in File$i",
        )

    private fun report(
        findings: List<Finding>,
        skipped: List<SkippedRuleInfo> = emptyList(),
    ) = ValidationReport(
        passed = false,
        findings = findings,
        summary = findings.summarize(),
        groupedByLocation = emptyMap(),
        inlineEligible = emptyList(),
        summaryOnly = findings,
        complianceChecklist = emptyList(),
        explanations = emptyMap(),
        metadata = ReportMetadata(version = "test", timestamp = 0L),
        skippedRules = skipped,
    )

    @Test
    fun `summary of a 140 file MR is collapsed to at most 10 KB`() {
        val findings = (1..140).map(::finding)
        val skipped = (1..40).map { SkippedRuleInfo("skipped-rule-$it", "file pattern did not match any of the 140 changed files") }
        val r = report(findings, skipped)

        val md = formatSummaryMarkdown(r, r.summaryOnly, inlineCount = 0)

        assertTrue(md.encodeToByteArray().size <= SUMMARY_MAX_BYTES, "summary is ${md.encodeToByteArray().size} bytes")
        assertTrue("<details><summary>Findings (140)</summary>" in md, md)
        assertTrue("more findings not shown" in md, md)
        assertEquals(md.split("<details>").size, md.split("</details>").size, "unbalanced details tags")
        assertTrue(md.trimEnd().endsWith(SUMMARY_FOOTER), md.takeLast(200))
    }

    @Test
    fun `small summary is not collapsed`() {
        val r = report((1..3).map(::finding))

        val md = formatSummaryMarkdown(r, r.summaryOnly, inlineCount = 0)

        assertFalse("<details><summary>Findings" in md, md)
        assertTrue("| ❌ ERROR | `rule-3` |" in md, md)
    }
}
